        d["To, czego ja nie zrobiłem. Cokolwiek to jest."] = "Те, чого не зробив я. Що б це не було.";
        d["Trasa, wagon, miejsce i numer. Imię na bilecie musi zgadzać się z dowodem."] = "Маршрут, вагон, місце й номер. Ім’я на квитку має збігатися з посвідченням.";
        d["Trzynasty"] = "Тринадцятий";
        d["Tu coś jest nie tak: "] = "Тут щось не так: ";
        d["Twarz na dowodzie należy do kogoś innego. Najprostszy sposób na poznanie podszywacza."] = "Обличчя на посвідченні належить комусь іншому. Найпростіший спосіб розпізнати самозванця.";
        d["Twoja decyzja."] = "Твоє рішення.";
        d["Twoje biurko, lampa i stos dokumentów. Drewno jest tak stare, że pamięta zmiany, których ty nie pamiętasz."] = "Твій стіл, лампа й стос документів. Дерево таке старе, що пам’ятає зміни, яких не пам’ятаєш ти.";
        d["Twoje zdjęcie"] = "Твоє фото";
        d["Ty też jesteś jak ja? Zawsze na peronie?"] = "Ти теж такий, як я? Завжди на пероні?";
        d["Ty. Jan Ostoja, numer służbowy K-13-0013. W aktach brakuje daty urodzenia i daty zatrudnienia. Jest tylko dopisek: \"na stanowisku od zawsze\"."] = "Ти. Ян Остоя, службовий номер K-13-0013. В особовій справі бракує дати народження й дати прийняття на роботу. Є лише примітка: «на посаді відвіку».";
        d["Ty: "] = "Ти: ";
