        d["Wagon 13"] = "Вагон 13";
        d["Wagon 13  Miejsce 13"] = "Вагон 13  Місце 13";
        d["Wagon 13 jest zamknięty. Żywi i zmarli z biletem mogą jechać."] = "Вагон 13 замкнений. Живі й померлі з квитком можуть їхати.";
        d["Wagon 13 nie figuruje w manifeście."] = "Вагона 13 у маніфесті немає.";
        d["Wagon zamknięty od zewnątrz. Nie figuruje w manifeście. Czasem ktoś puka od środka."] = "Вагон, замкнений ззовні. Його немає в маніфесті. Іноді зсередини хтось стукає.";
        d["Wcześniej stałem tam, gdzie pan teraz."] = "Раніше я стояв там, де тепер стоїте ви.";
        d["Wersja 2.0   Trzynaście osób. Zawsze trzynaście."] = "Версія 2.0   Тринадцять людей. Завжди тринадцять.";
        d["Wezmę ją za rękę. I tyle. Nic więcej mi nie trzeba."] = "Візьму її за руку. І все. Більше мені нічого не треба.";
        d["Weź mnie ze sobą."] = "Візьми мене з собою.";
        d["Wieczór, szefie. Naprawa toru na końcu peronu. Papiery w porządku."] = "Добрий вечір, шефе. Ремонт колії в кінці перону. Папери в порядку.";
        d["Więcej oznaczeń podejrzanych szczegółów i wyczucie, że coś jest nie tak z osobą."] = "Більше позначок на підозрілих деталях і відчуття, що з людиною щось не так.";
        d["Więcej pytań i wykrywanie kłamstw w odpowiedziach."] = "Більше запитань і вміння викривати брехню у відповідях.";
        d["Wpis o śmierci"] = "Запис про смерть";
        d["Wpis urzędowy jest ostateczny."] = "Офіційний запис є остаточним.";
        d["Wpuszczaj tylko żywych."] = "Пропускай лише живих.";
        d["Wpuszczaj tylko żywych. Osobom bez wpisu w Rejestrze odmawiaj."] = "Пропускай лише живих. Тим, кого немає в Реєстрі, відмовляй.";
        d["Wpuszczasz kogoś, kogo nie ma."] = "Ти пропускаєш когось, кого не існує.";
        d["Wpuszczasz siebie i wiesz już, kim jesteś. Jan Ostoja, konduktor, który przed laty odmówił sobie miejsca w pociągu i został na peronie. Każdy kolejny konduktor to on. Każda noc to ta sama noc.\n\nDrzwi otwierają się z cichym westchnieniem. W wagonach siedzą ci, których nie zostawiłeś na peronie. Pociąg rusza, a peron 13 po raz pierwszy jest pusty. Nie musiałeś być tylko konduktorem od zasad. Musiałeś tylko przeczytać własne dokumenty."] = "Ти пропускаєш самого себе й нарешті знаєш, хто ти. Ян Остоя, провідник, який багато років тому відмовив собі в місці в поїзді й залишився на пероні. Кожен наступний провідник — це він. Кожна ніч — та сама ніч.\n\nДвері відчиняються з тихим зітханням. У вагонах сидять ті, кого ти не залишив на пероні. Поїзд рушає, а перон 13 уперше порожній. Тобі не треба було бути лише провідником, що дотримується правил. Досить було прочитати власні документи.";
        d["Wpuszczasz siebie, ale nie wiesz, po co. Pociąg rusza, wagony są pełne i ciche. Za oknem migają lampy peronu, ciągle te same. Ktoś obok mówi twoim głosem: \"Bilety do kontroli\".\n\nJesteś teraz częścią składu. Następnej nocy na peronie pojawi się nowy konduktor i nikt mu nie powie, że poprzedni jedzie w wagonie trzynastym. Kolej działa bez zarzutu. Tylko dokąd?"] = "Ти пропускаєш самого себе, але не знаєш, навіщо. Поїзд рушає, вагони повні й тихі. За вікном миготять ліхтарі перону, щоразу ті самі. Хтось поруч каже твоїм голосом: «Квитки до контролю».\n\nТепер ти — частина складу. Наступної ночі на пероні з’явиться новий провідник, і ніхто не скаже йому, що попередній їде у тринадцятому вагоні. Залізниця працює бездоганно. Але куди?";
        d["Wpuszczeni jadą do stacji 13. Nikt ich nie widział ponownie. Nikt też nie widział, żeby ktoś stamtąd wracał głodny."] = "Пропущені їдуть до станції 13. Ніхто їх більше не бачив. Ніхто також не бачив, щоб хтось звідти повертався голодним.";
        d["Wpuszczono"] = "Пропущено";
        d["Wpuścisz mnie? Mama czeka w wagonie."] = "Ти мене пропустиш? Мама чекає у вагоні.";
        d["Wpuść człowieka bez dokumentów."] = "Пропусти людину без документів.";
        d["Wpuść zmarłego pasażera."] = "Пропусти померлого пасажира.";
        d["Wróciłam. Nie umiem inaczej."] = "Я повернулася. Інакше не вмію.";
        d["Wszyscy, których pan nie wpuścił."] = "Усі, кого ви не пропустили.";
        d["Wszystkie moje zegarki stanęły w tej samej chwili. Wie pan, w której."] = "Усі мої годинники зупинилися в ту саму мить. Ви знаєте, в яку.";
        d["Wybierz drugą kartkę zakładką u góry."] = "Обери другий аркуш вкладкою вгорі.";
        d["Wynik serii: "] = "Результат серії: ";
