        d["Za drobne, żeby przeczytać. Użyj skanu mikrotekstu (potrzebny odpowiedni poziom DOKUMENTÓW)."] = "Занадто дрібно, щоб прочитати. Скористайся сканом мікротексту (потрібен відповідний рівень навички ДОКУМЕНТИ).";
        d["Za peronem 13 jest jeszcze jeden. Nie ma go w Rejestrze, więc jest jedynym miejscem, gdzie kolej nie sięga."] = "За пероном 13 є ще один. Його немає в Реєстрі, тож це єдине місце, куди залізниця не сягає.";
        d["Za późno, konduktorze. Ale jeszcze nie za późno dla pana."] = "Запізно, провіднику. Але для вас іще не запізно.";
        d["Zajezdnia 4"] = "Депо 4";
        d["Zakończenia: "] = "Кінцівки: ";
        d["Zamki. Ostatnio jeden bardzo uparty. Wagon trzynasty."] = "Замки. Останнім часом один дуже впертий. Тринадцятий вагон.";
        d["Zapyta pan, czy jestem żywy. To niewłaściwe pytanie."] = "Ви спитаєте, чи я живий. Це хибне запитання.";
        d["Zatrzymany zegar"] = "Зупинений годинник";
        d["Zawsze jest trzynaście osób. Dwanaście z nich to pasażerowie. Kim jest trzynasta?"] = "Завжди є тринадцять осіб. Дванадцять із них — пасажири. Хто тринадцятий?";
        d["Zbyt wiele błędów w jedną noc. Dyrekcja zabiera ci mundur.\n\nBłędy tej nocy: "] = "Забагато помилок за одну ніч. Дирекція забирає в тебе мундир.\n\nПомилки цієї ночі: ";
        d["Zdjęcie jest puste. Papier nie zna twarzy tej osoby."] = "Фото порожнє. Папір не знає обличчя цієї людини.";
        d["Zdjęcie przedstawia ciebie. To twoja twarz. Nawet mundur się zgadza."] = "На фото — ти. Це твоє обличчя. Навіть мундир збігається.";
        d["Zdjęcie przedstawia kogoś innego niż osoba przed tobą."] = "На фото хтось інший, а не людина перед тобою.";
        d["Zdjęcie się nie zgadza"] = "Фото не збігається";
        d["Zegar na peronie staje o 03:13. Godzinę później nadal jest 03:13."] = "Годинник на пероні зупиняється о 03:13. Через годину все ще 03:13.";
        d["Zegar na peronie zatrzymał się o 03:13. Rano znów chodził, jakby nic się nie stało. Ale wskazówki były przesunięte o jedną kreskę."] = "Годинник на пероні зупинився о 03:13. Уранці він знову йшов, ніби нічого не сталося. Але стрілки були зсунуті на одну поділку.";
        d["Zegar zatrzymał się na 03:13."] = "Годинник зупинився на 03:13.";
        d["Zegarmistrz. Naprawiałem cudzy czas. Swojego nie potrafiłem."] = "Годинникар. Лагодив чужий час. Свого не зумів.";
        d["Zeszłej nocy odesłał mnie pan. Nic nie szkodzi. Wystarczy, że jutro znów mogę spróbować."] = "Учора ви мене відправили назад. Нічого страшного. Досить того, що завтра я знову можу спробувати.";
        d["Zeszłej nocy zostałem na peronie. Było mi zimno. Teraz już nie jest."] = "Учора я залишився на пероні. Мені було холодно. Тепер уже ні.";
        d["Zgasły wszystkie światła."] = "Погасли всі світла.";
