        d["Zmarli"] = "Померлі";
        d["Zmarli z ważnym biletem mogą jechać. Nieistniejącym i fałszerzom odmawiaj."] = "Померлі з дійсним квитком можуть їхати. Неіснуючим і фальсифікаторам відмовляй.";
        d["Zmiana bez końca"] = "Зміна без кінця";
